#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>
#include <limits.h>

#define MAX_IMAGE_DIMENSION 65535
#define MAX_TOTAL_PIXELS 268435456  /* 256 megapixels */
#define HEADER_MAGIC 0x42495447  /* "BITG" */
#define MAX_CHANNELS 4

typedef struct {
    uint32_t magic;
    uint32_t width;
    uint32_t height;
    uint8_t  channels;
    uint8_t  bit_depth;
    uint16_t compression;
    uint32_t data_offset;
    uint32_t data_length;
} __attribute__((packed)) ImageHeader;

typedef struct {
    uint8_t *pixels;
    uint32_t width;
    uint32_t height;
    uint8_t  channels;
    size_t   buffer_size;
} ImageBuffer;

/* Validate header fields independently */
static int validate_dimensions(uint32_t width, uint32_t height) {
    if (width == 0 || height == 0) return -1;
    if (width > MAX_IMAGE_DIMENSION) return -1;
    if (height > MAX_IMAGE_DIMENSION) return -1;
    /* Check total pixel count to prevent excessive memory use */
    uint64_t total_pixels = (uint64_t)width * (uint64_t)height;
    if (total_pixels > MAX_TOTAL_PIXELS) return -1;
    return 0;
}

static int validate_channels(uint8_t channels) {
    if (channels == 0 || channels > MAX_CHANNELS) return -1;
    return 0;
}

static int validate_bit_depth(uint8_t bit_depth) {
    /* Only support 8 and 16 bit depths */
    if (bit_depth != 8 && bit_depth != 16) return -1;
    return 0;
}

static int validate_header(const ImageHeader *hdr) {
    if (hdr->magic != HEADER_MAGIC) return -1;
    if (validate_dimensions(hdr->width, hdr->height) != 0) return -1;
    if (validate_channels(hdr->channels) != 0) return -1;
    if (validate_bit_depth(hdr->bit_depth) != 0) return -1;
    if (hdr->data_offset < sizeof(ImageHeader)) return -1;
    return 0;
}

/*
 * Calculate required buffer size for decoded image.
 * Returns 0 on overflow.
 */
static size_t calculate_buffer_size(uint32_t width, uint32_t height,
                                    uint8_t channels, uint8_t bit_depth) {
    /* bytes_per_pixel = channels * (bit_depth / 8) */
    uint32_t bytes_per_pixel = (uint32_t)channels * (bit_depth / 8);

    /* row_stride includes alignment padding to 16 bytes */
    uint32_t row_bytes = width * bytes_per_pixel;
    uint32_t row_stride = (row_bytes + 15) & ~15u;

    /* Total buffer = row_stride * height */
    size_t total = (size_t)row_stride * (size_t)height;

    /* Overflow check: verify total / height == row_stride */
    if (height != 0 && total / height != row_stride) return 0;

    return total;
}

/*
 * Decode RLE-compressed image data into pixel buffer.
 * The RLE format: [count][value...] where count is a uint16_t
 * and value is bytes_per_pixel bytes.
 */
static int decode_rle(const uint8_t *src, uint32_t src_len,
                      uint8_t *dst, size_t dst_size,
                      uint32_t bytes_per_pixel) {
    size_t src_pos = 0;
    size_t dst_pos = 0;

    while (src_pos < src_len && dst_pos < dst_size) {
        if (src_pos + 2 > src_len) return -1;
        uint16_t run_length = (uint16_t)(src[src_pos] | (src[src_pos + 1] << 8));
        src_pos += 2;

        if (run_length == 0) continue;
        if (src_pos + bytes_per_pixel > src_len) return -1;

        /* Check destination bounds */
        size_t write_size = (size_t)run_length * bytes_per_pixel;
        if (dst_pos + write_size > dst_size) return -1;

        /* Write repeated pixel value */
        for (uint16_t i = 0; i < run_length; i++) {
            memcpy(dst + dst_pos, src + src_pos, bytes_per_pixel);
            dst_pos += bytes_per_pixel;
        }
        src_pos += bytes_per_pixel;
    }
    return 0;
}

/*
 * Main image loading function.
 * Reads from a file descriptor, validates, allocates, and decodes.
 */
ImageBuffer* load_image(const char *filepath) {
    FILE *fp = fopen(filepath, "rb");
    if (!fp) return NULL;

    ImageHeader hdr;
    if (fread(&hdr, sizeof(hdr), 1, fp) != 1) {
        fclose(fp);
        return NULL;
    }

    if (validate_header(&hdr) != 0) {
        fclose(fp);
        return NULL;
    }

    size_t buf_size = calculate_buffer_size(hdr.width, hdr.height,
                                            hdr.channels, hdr.bit_depth);
    if (buf_size == 0) {
        fclose(fp);
        return NULL;
    }

    /* Validate data_length against file and reasonable bounds */
    if (hdr.data_length == 0 || hdr.data_length > 0x40000000) {
        fclose(fp);
        return NULL;
    }

    /* Seek to data offset */
    if (fseek(fp, hdr.data_offset, SEEK_SET) != 0) {
        fclose(fp);
        return NULL;
    }

    /* Read compressed data */
    uint8_t *compressed = (uint8_t *)malloc(hdr.data_length);
    if (!compressed) {
        fclose(fp);
        return NULL;
    }

    if (fread(compressed, 1, hdr.data_length, fp) != hdr.data_length) {
        free(compressed);
        fclose(fp);
        return NULL;
    }
    fclose(fp);

    /* Allocate output buffer */
    ImageBuffer *img = (ImageBuffer *)calloc(1, sizeof(ImageBuffer));
    if (!img) {
        free(compressed);
        return NULL;
    }

    img->pixels = (uint8_t *)malloc(buf_size);
    if (!img->pixels) {
        free(img);
        free(compressed);
        return NULL;
    }

    img->width = hdr.width;
    img->height = hdr.height;
    img->channels = hdr.channels;
    img->buffer_size = buf_size;

    /* Decode based on compression type */
    uint32_t bytes_per_pixel = (uint32_t)hdr.channels * (hdr.bit_depth / 8);

    if (hdr.compression == 1) {
        /* RLE compressed */
        if (decode_rle(compressed, hdr.data_length,
                       img->pixels, buf_size, bytes_per_pixel) != 0) {
            free(img->pixels);
            free(img);
            free(compressed);
            return NULL;
        }
    } else if (hdr.compression == 0) {
        /* Uncompressed: copy directly */
        size_t expected = (size_t)hdr.width * hdr.height * bytes_per_pixel;
        if (hdr.data_length < expected) {
            free(img->pixels);
            free(img);
            free(compressed);
            return NULL;
        }
        memcpy(img->pixels, compressed, expected);
    } else {
        free(img->pixels);
        free(img);
        free(compressed);
        return NULL;
    }

    free(compressed);
    return img;
}

void free_image(ImageBuffer *img) {
    if (img) {
        free(img->pixels);
        free(img);
    }
}
